1	// Phase 1 exploratory prototype — Bookmark library
2	// Iteration 5: TAGS for organizing — tags shown on each entry, add/remove tags,
3	//   and filter the current view by one OR several tags (match ALL selected).
4	// Carries approved behaviour: quick save, auto-fill, readable list, duplicate
5	//   handling, read/archive states with All / Unread / Archived views.
6	// Exploration prototype only — NOT production code; must not seed Phase 2.
7	
8	const http = require('http');
9	
10	const PORT = 4001;
11	const HOST = '0.0.0.0';
12	
13	/** In-memory store (prototype only). Each entry: {read, archived, tags:[]}. */
14	const bookmarks = [];
15	let nextId = 1;
16	
17	function seed() {
18	  const now = Date.now();
19	  const samples = [
20	    { url: 'https://developer.mozilla.org/en-US/docs/Web/CSS/Grid',
21	      title: 'CSS Grid Layout — MDN',
22	      description: 'A two-dimensional layout system for the web, with rows and columns.',
23	      siteName: 'developer.mozilla.org', read: false, archived: false, ageMin: 8,
24	      tags: ['css', 'reference'] },
25	    { url: 'https://www.nngroup.com/articles/progressive-disclosure/',
26	      title: 'Progressive Disclosure — Nielsen Norman Group',
27	      description: 'Defer advanced or rarely used features to a secondary screen to keep interfaces calm.',
28	      siteName: 'nngroup.com', read: false, archived: false, ageMin: 40,
29	      tags: ['ux', 'reading'] },
30	    { url: 'https://en.wikipedia.org/wiki/Zettelkasten',
31	      title: 'Zettelkasten — Wikipedia',
32	      description: 'A method of personal knowledge management and note-taking.',
33	      siteName: 'en.wikipedia.org', read: true, archived: false, ageMin: 130,
34	      tags: ['notes', 'method'] },
35	    { url: 'https://www.gutenberg.org/ebooks/1342',
36	      title: 'Pride and Prejudice, by Jane Austen — Project Gutenberg',
37	      description: 'The complete text, free to read.',
38	      siteName: 'gutenberg.org', read: true, archived: true, ageMin: 1500,
39	      tags: ['book'] },
40	    { url: 'https://web.archive.org/',
41	      title: 'Internet Archive: Wayback Machine',
42	      description: 'Explore archived snapshots of web pages over time.',
43	      siteName: 'web.archive.org', read: false, archived: true, ageMin: 6000,
44	      tags: ['tools', 'reference'] },
45	  ];
46	  for (const s of samples) {
47	    const host = new URL(s.url).hostname.replace(/^www\./, '');
48	    bookmarks.push({
49	      id: nextId++, url: s.url, key: canonicalKey(s.url),
50	      title: s.title, description: s.description, siteName: s.siteName,
51	      favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
52	      retrieved: true, read: s.read, archived: s.archived, tags: s.tags.slice(),
53	      savedAt: new Date(now - s.ageMin * 60000).toISOString(),
54	    });
55	  }
56	  bookmarks.sort((a, b) => new Date(b.savedAt) - new Date(a.savedAt));
57	}
58	
59	// ---- metadata retrieval -----------------------------------------------------
60	
61	function decodeEntities(s) {
62	  if (!s) return s;
63	  return s
64	    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
65	    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x27;/g, "'")
66	    .replace(/&nbsp;/g, ' ')
67	    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
68	    .trim();
69	}
70	function metaContent(html, patterns) {
71	  for (const re of patterns) {
72	    const m = re.exec(html);
73	    if (m && m[1] && m[1].trim()) return decodeEntities(m[1]);
74	  }
75	  return '';
76	}
77	function normalizeUrl(raw) {
78	  let u = (raw || '').trim();
79	  if (!u) return '';
80	  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
81	  try { return new URL(u).toString(); } catch { return ''; }
82	}
83	function canonicalKey(url) {
84	  try {
85	    const p = new URL(url);
86	    const host = p.hostname.replace(/^www\./, '').toLowerCase();
87	    let path = p.pathname.replace(/\/+$/, '');
88	    if (path === '') path = '/';
89	    return host + path + p.search;
90	  } catch { return url; }
91	}
92	async function fetchMetadata(url) {
93	  const parsed = new URL(url);
94	  const host = parsed.hostname.replace(/^www\./, '');
95	  const result = { title: '', description: '', siteName: host,
96	    favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`, retrieved: false };
97	  try {
98	    const controller = new AbortController();
99	    const timer = setTimeout(() => controller.abort(), 8000);
100	    const res = await fetch(url, {
101	      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BookmarkPrototype/1.0)' },
102	      signal: controller.signal, redirect: 'follow' });
103	    clearTimeout(timer);
104	    const html = (await res.text()).slice(0, 400000);
105	    result.title = metaContent(html, [
106	      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
107	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
108	      /<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["']/i,
109	      /<title[^>]*>([\s\S]*?)<\/title>/i ]);
110	    result.description = metaContent(html, [
111	      /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
112	      /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i,
113	      /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
114	      /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i ]);
115	    const site = metaContent(html, [
116	      /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i,
117	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:site_name["']/i ]);
118	    if (site) result.siteName = site;
119	    result.retrieved = true;
120	  } catch { result.retrieved = false; }
121	  if (!result.title) result.title = host + parsed.pathname.replace(/\/$/, '');
122	  return result;
123	}
124	
125	// ---- api --------------------------------------------------------------------
126	
127	function readBody(req) {
128	  return new Promise((resolve) => {
129	    let data = '';
130	    req.on('data', (c) => (data += c));
131	    req.on('end', () => resolve(data));
132	  });
133	}
134	function json(res, code, obj) {
135	  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
136	  res.end(JSON.stringify(obj));
137	}
138	function normTag(t) { return (t || '').trim().replace(/\s+/g, ' ').slice(0, 40); }
139	
140	async function handleSave(req, res) {
141	  const body = await readBody(req);
142	  let url = '';
143	  try { url = JSON.parse(body).url; } catch {}
144	  const normalized = normalizeUrl(url);
145	  if (!normalized) return json(res, 400, { error: 'invalid_url' });
146	  const key = canonicalKey(normalized);
147	  const existing = bookmarks.find((b) => b.key === key);
148	  if (existing) return json(res, 200, { bookmark: existing, duplicate: true });
149	  const meta = await fetchMetadata(normalized);
150	  const entry = {
151	    id: nextId++, url: normalized, key,
152	    title: meta.title, description: meta.description, siteName: meta.siteName,
153	    favicon: meta.favicon, retrieved: meta.retrieved,
154	    read: false, archived: false, tags: [],
155	    savedAt: new Date().toISOString() };
156	  bookmarks.unshift(entry);
157	  json(res, 200, { bookmark: entry, duplicate: false });
158	}
159	
160	async function handleField(req, res, field) {
161	  const body = await readBody(req);
162	  let id, value;
163	  try { ({ id, value } = JSON.parse(body)); } catch {}
164	  if (typeof value !== 'boolean') return json(res, 400, { error: 'bad_value' });
165	  const b = bookmarks.find((x) => x.id === id);
166	  if (!b) return json(res, 404, { error: 'not_found' });
167	  b[field] = value;
168	  json(res, 200, { bookmark: b });
169	}
170	
171	async function handleTag(req, res, add) {
172	  const body = await readBody(req);
173	  let id, tag;
174	  try { ({ id, tag } = JSON.parse(body)); } catch {}
175	  const b = bookmarks.find((x) => x.id === id);
176	  if (!b) return json(res, 404, { error: 'not_found' });
177	  const t = normTag(tag);
178	  if (!t) return json(res, 400, { error: 'empty_tag' });

