attachment.snippet:
1	// Phase 1 exploratory prototype — Bookmark library
2	// Iteration 7: richer save & edit —
3	//   * review/correct the auto-filled title & description BEFORE finalizing a save
4	//   * edit an entry's address too (with duplicate-address guard)
5	//   * notes support simple formatting (headings/bold/lists/links), rendered on view
6	// Carries approved behaviour: quick save, auto-fill, readable list, duplicate
7	//   handling, read/archive states with All / Unread / Archived views, tags with
8	//   single- and multi-tag (match-all) filtering, editing title/description/note.
9	// Exploration prototype only — NOT production code; must not seed Phase 2.
10	
11	const http = require('http');
12	
13	const PORT = 4001;
14	const HOST = '0.0.0.0';
15	
16	/** In-memory store (prototype only). Each entry: {read, archived, tags:[]}. */
17	const bookmarks = [];
18	let nextId = 1;
19	
20	function seed() {
21	  const now = Date.now();
22	  const samples = [
23	    { url: 'https://developer.mozilla.org/en-US/docs/Web/CSS/Grid',
24	      title: 'CSS Grid Layout — MDN',
25	      description: 'A two-dimensional layout system for the web, with rows and columns.',
26	      siteName: 'developer.mozilla.org', read: false, archived: false, ageMin: 8,
27	      tags: ['css', 'reference', 'web'] },
28	    { url: 'https://www.nngroup.com/articles/progressive-disclosure/',
29	      title: 'Progressive Disclosure — Nielsen Norman Group',
30	      description: 'Defer advanced or rarely used features to a secondary screen to keep interfaces calm.',
31	      siteName: 'nngroup.com', read: false, archived: false, ageMin: 40,
32	      tags: ['ux', 'reading', 'web'],
33	      note: 'Re-read before redesigning the settings screen.' },
34	    { url: 'https://en.wikipedia.org/wiki/Zettelkasten',
35	      title: 'Zettelkasten — Wikipedia',
36	      description: 'A method of personal knowledge management and note-taking.',
37	      siteName: 'en.wikipedia.org', read: true, archived: false, ageMin: 130,
38	      tags: ['notes', 'method', 'reading'] },
39	    { url: 'https://www.gutenberg.org/ebooks/1342',
40	      title: 'Pride and Prejudice, by Jane Austen — Project Gutenberg',
41	      description: 'The complete text, free to read.',
42	      siteName: 'gutenberg.org', read: true, archived: true, ageMin: 1500,
43	      tags: ['book'] },
44	    { url: 'https://web.archive.org/',
45	      title: 'Internet Archive: Wayback Machine',
46	      description: 'Explore archived snapshots of web pages over time.',
47	      siteName: 'web.archive.org', read: false, archived: true, ageMin: 6000,
48	      tags: ['tools', 'reference'] },
49	  ];
50	  for (const s of samples) {
51	    const host = new URL(s.url).hostname.replace(/^www\./, '');
52	    bookmarks.push({
53	      id: nextId++, url: s.url, key: canonicalKey(s.url),
54	      title: s.title, description: s.description, siteName: s.siteName,
55	      favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
56	      retrieved: true, read: s.read, archived: s.archived, tags: s.tags.slice(),
57	      note: s.note || '',
58	      savedAt: new Date(now - s.ageMin * 60000).toISOString(),
59	    });
60	  }
61	  bookmarks.sort((a, b) => new Date(b.savedAt) - new Date(a.savedAt));
62	}
63	
64	// ---- metadata retrieval -----------------------------------------------------
65	
66	function decodeEntities(s) {
67	  if (!s) return s;
68	  return s
