1	// Phase 1 exploratory prototype — Bookmark library
2	// Iteration 8: SEARCH across titles, descriptions, tags, notes, and address —
3	//   searches the whole library (all views), highlights matches.
4	// Carries all approved behaviour through iteration 7.
5	// Exploration prototype only — NOT production code; must not seed Phase 2.
6	
7	const http = require('http');
8	
9	const PORT = 4001;
10	const HOST = '0.0.0.0';
11	
12	/** In-memory store (prototype only). Each entry: {read, archived, tags:[]}. */
13	const bookmarks = [];
14	let nextId = 1;
15	
16	function seed() {
17	  const now = Date.now();
18	  const samples = [
19	    { url: 'https://developer.mozilla.org/en-US/docs/Web/CSS/Grid',
20	      title: 'CSS Grid Layout — MDN',
21	      description: 'A two-dimensional layout system for the web, with rows and columns.',
22	      siteName: 'developer.mozilla.org', read: false, archived: false, ageMin: 8,
23	      tags: ['css', 'reference', 'web'] },
24	    { url: 'https://www.nngroup.com/articles/progressive-disclosure/',
25	      title: 'Progressive Disclosure — Nielsen Norman Group',
26	      description: 'Defer advanced or rarely used features to a secondary screen to keep interfaces calm.',
27	      siteName: 'nngroup.com', read: false, archived: false, ageMin: 40,
28	      tags: ['ux', 'reading', 'web'],
29	      note: 'Re-read before redesigning the settings screen.' },
30	    { url: 'https://en.wikipedia.org/wiki/Zettelkasten',
31	      title: 'Zettelkasten — Wikipedia',
32	      description: 'A method of personal knowledge management and note-taking.',
33	      siteName: 'en.wikipedia.org', read: true, archived: false, ageMin: 130,
34	      tags: ['notes', 'method', 'reading'] },
35	    { url: 'https://www.gutenberg.org/ebooks/1342',
36	      title: 'Pride and Prejudice, by Jane Austen — Project Gutenberg',
37	      description: 'The complete text, free to read.',
38	      siteName: 'gutenberg.org', read: true, archived: true, ageMin: 1500,
39	      tags: ['book'] },
40	    { url: 'https://web.archive.org/',
41	      title: 'Internet Archive: Wayback Machine',
42	      description: 'Explore archived snapshots of web pages over time.',
43	      siteName: 'web.archive.org', read: false, archived: true, ageMin: 6000,
44	      tags: ['tools', 'reference'] },
45	  ];
46	  for (const s of samples) {
47	    const host = new URL(s.url).hostname.replace(/^www\./, '');
48	    bookmarks.push({
49	      id: nextId++, url: s.url, key: canonicalKey(s.url),
50	      title: s.title, description: s.description, siteName: s.siteName,
51	      favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
52	      retrieved: true, read: s.read, archived: s.archived, tags: s.tags.slice(),
53	      note: s.note || '',
54	      savedAt: new Date(now - s.ageMin * 60000).toISOString(),
55	    });
56	  }
57	  bookmarks.sort((a, b) => new Date(b.savedAt) - new Date(a.savedAt));
58	}
59	
60	// ---- metadata retrieval -----------------------------------------------------
61	
62	function decodeEntities(s) {
63	  if (!s) return s;
64	  return s
65	    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
66	    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x27;/g, "'")
67	    .replace(/&nbsp;/g, ' ')
68	    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
69	    .trim();
70	}
71	function metaContent(html, patterns) {
72	  for (const re of patterns) {
73	    const m = re.exec(html);
74	    if (m && m[1] && m[1].trim()) return decodeEntities(m[1]);
75	  }
76	  return '';
77	}
78	function normalizeUrl(raw) {
79	  let u = (raw || '').trim();
80	  if (!u) return '';
81	  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
82	  try { return new URL(u).toString(); } catch { return ''; }
83	}
84	function canonicalKey(url) {
85	  try {
86	    const p = new URL(url);
87	    const host = p.hostname.replace(/^www\./, '').toLowerCase();
88	    let path = p.pathname.replace(/\/+$/, '');
89	    if (path === '') path = '/';
90	    return host + path + p.search;
91	  } catch { return url; }
92	}
93	async function fetchMetadata(url) {
94	  const parsed = new URL(url);
95	  const host = parsed.hostname.replace(/^www\./, '');
96	  const result = { title: '', description: '', siteName: host,
97	    favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`, retrieved: false };
98	  try {
99	    const controller = new AbortController();
100	    const timer = setTimeout(() => controller.abort(), 8000);
101	    const res = await fetch(url, {
102	      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BookmarkPrototype/1.0)' },
103	      signal: controller.signal, redirect: 'follow' });
104	    clearTimeout(timer);
105	    const html = (await res.text()).slice(0, 400000);
106	    result.title = metaContent(html, [
107	      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
108	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
109	      /<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["']/i,
110	      /<title[^>]*>([\s\S]*?)<\/title>/i ]);
111	    result.description = metaContent(html, [
112	      /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
113	      /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i,
114	      /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
115	      /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i ]);
116	    const site = metaContent(html, [
117	      /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i,
118	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:site_name["']/i ]);
119	    if (site) result.siteName = site;
120	    result.retrieved = true;
121	  } catch { result.retrieved = false; }
122	  if (!result.title) result.title = host + parsed.pathname.replace(/\/$/, '');
123	  return result;
124	}
125	
126	// ---- api --------------------------------------------------------------------
127	
128	function readBody(req) {
129	  return new Promise((resolve) => {
130	    let data = '';
131	    req.on('data', (c) => (data += c));
132	    req.on('end', () => resolve(data));
133	  });
134	}
135	function json(res, code, obj) {
136	  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
137	  res.end(JSON.stringify(obj));
138	}
139	function normTag(t) { return (t || '').trim().replace(/\s+/g, ' ').slice(0, 40); }
140	
141	async function handleSave(req, res) {
142	  const body = await readBody(req);
143	  let url = '';
144	  try { url = JSON.parse(body).url; } catch {}
145	  const normalized = normalizeUrl(url);
