1	// Phase 1 exploratory prototype — Bookmark library
2	// Iteration 8b: SEARCH within the current view (All / Unread / Archived) across
3	//   titles, descriptions, tags, notes, address. Query language: #tag, "exact
4	//   phrase", AND / OR / NOT, parentheses; matches highlighted. Switching views
5	//   re-scopes the same query. Carries all approved behaviour through iteration 7.
6	// Exploration prototype only — NOT production code; must not seed Phase 2.
7	
8	const http = require('http');
9	
10	const PORT = 4001;
11	const HOST = '0.0.0.0';
12	
13	/** In-memory store (prototype only). Each entry: {read, archived, tags:[]}. */
14	const bookmarks = [];
15	let nextId = 1;
16	
17	function seed() {
18	  const now = Date.now();
19	  const samples = [
20	    { url: 'https://developer.mozilla.org/en-US/docs/Web/CSS/Grid',
21	      title: 'CSS Grid Layout — MDN',
22	      description: 'A two-dimensional layout system for the web, with rows and columns.',
23	      siteName: 'developer.mozilla.org', read: false, archived: false, ageMin: 8,
24	      tags: ['css', 'reference', 'web'] },
25	    { url: 'https://www.nngroup.com/articles/progressive-disclosure/',
26	      title: 'Progressive Disclosure — Nielsen Norman Group',
27	      description: 'Defer advanced or rarely used features to a secondary screen to keep interfaces calm.',
28	      siteName: 'nngroup.com', read: false, archived: false, ageMin: 40,
29	      tags: ['ux', 'reading', 'web'],
30	      note: 'Re-read before redesigning the settings screen.' },
31	    { url: 'https://en.wikipedia.org/wiki/Zettelkasten',
32	      title: 'Zettelkasten — Wikipedia',
33	      description: 'A method of personal knowledge management and note-taking.',
34	      siteName: 'en.wikipedia.org', read: true, archived: false, ageMin: 130,
35	      tags: ['notes', 'method', 'reading'] },
36	    { url: 'https://www.gutenberg.org/ebooks/1342',
37	      title: 'Pride and Prejudice, by Jane Austen — Project Gutenberg',
38	      description: 'The complete text, free to read.',
39	      siteName: 'gutenberg.org', read: true, archived: true, ageMin: 1500,
40	      tags: ['book'] },
41	    { url: 'https://web.archive.org/',
42	      title: 'Internet Archive: Wayback Machine',
43	      description: 'Explore archived snapshots of web pages over time.',
44	      siteName: 'web.archive.org', read: false, archived: true, ageMin: 6000,
45	      tags: ['tools', 'reference'] },
46	  ];
47	  for (const s of samples) {
48	    const host = new URL(s.url).hostname.replace(/^www\./, '');
49	    bookmarks.push({
50	      id: nextId++, url: s.url, key: canonicalKey(s.url),
51	      title: s.title, description: s.description, siteName: s.siteName,
52	      favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
53	      retrieved: true, read: s.read, archived: s.archived, tags: s.tags.slice(),
54	      note: s.note || '',
55	      savedAt: new Date(now - s.ageMin * 60000).toISOString(),
56	    });
57	  }
58	  bookmarks.sort((a, b) => new Date(b.savedAt) - new Date(a.savedAt));
59	}
60	
61	// ---- metadata retrieval -----------------------------------------------------
62	
63	function decodeEntities(s) {
64	  if (!s) return s;
65	  return s
66	    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
67	    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x27;/g, "'")
68	    .replace(/&nbsp;/g, ' ')
69	    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
70	    .trim();
71	}
72	function metaContent(html, patterns) {
73	  for (const re of patterns) {
74	    const m = re.exec(html);
75	    if (m && m[1] && m[1].trim()) return decodeEntities(m[1]);
76	  }
77	  return '';
78	}
79	function normalizeUrl(raw) {
80	  let u = (raw || '').trim();
81	  if (!u) return '';
82	  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
83	  try { return new URL(u).toString(); } catch { return ''; }
84	}
85	function canonicalKey(url) {
86	  try {
87	    const p = new URL(url);
88	    const host = p.hostname.replace(/^www\./, '').toLowerCase();
89	    let path = p.pathname.replace(/\/+$/, '');
90	    if (path === '') path = '/';
91	    return host + path + p.search;
92	  } catch { return url; }
93	}
94	async function fetchMetadata(url) {
95	  const parsed = new URL(url);
96	  const host = parsed.hostname.replace(/^www\./, '');
97	  const result = { title: '', description: '', siteName: host,
98	    favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`, retrieved: false };
99	  try {
100	    const controller = new AbortController();
101	    const timer = setTimeout(() => controller.abort(), 8000);
102	    const res = await fetch(url, {
103	      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BookmarkPrototype/1.0)' },
104	      signal: controller.signal, redirect: 'follow' });
105	    clearTimeout(timer);
106	    const html = (await res.text()).slice(0, 400000);
107	    result.title = metaContent(html, [
108	      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
109	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
110	      /<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["']/i,
111	      /<title[^>]*>([\s\S]*?)<\/title>/i ]);
112	    result.description = metaContent(html, [
113	      /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
114	      /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i,
115	      /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
116	      /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i ]);
117	    const site = metaContent(html, [
118	      /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i,
119	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:site_name["']/i ]);
120	    if (site) result.siteName = site;
121	    result.retrieved = true;
122	  } catch { result.retrieved = false; }
123	  if (!result.title) result.title = host + parsed.pathname.replace(/\/$/, '');
124	  return result;
125	}
126	
127	// ---- api --------------------------------------------------------------------
128	
129	function readBody(req) {
130	  return new Promise((resolve) => {
131	    let data = '';
132	    req.on('data', (c) => (data += c));
133	    req.on('end', () => resolve(data));
134	  });
135	}
136	function json(res, code, obj) {
137	  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
138	  res.end(JSON.stringify(obj));
139	}
140	function normTag(t) { return (t || '').trim().replace(/\s+/g, ' ').slice(0, 40); }
141	
142	async function handleSave(req, res) {
143	  const body = await readBody(req);
144	  let url = '';
145	  try { url = JSON.parse(body).url; } catch {}
146	  const normalized = normalizeUrl(url);
147	  if (!normalized) return json(res, 400, { error: 'invalid_url' });
148	  const key = canonicalKey(normalized);
149	  const existing = bookmarks.find((b) => b.key === key);
150	  if (existing) return json(res, 200, { bookmark: existing, duplicate: true });
151	  const meta = await fetchMetadata(normalized);
152	  const entry = {
153	    id: nextId++, url: normalized, key,
154	    title: meta.title, description: meta.description, siteName: meta.siteName,
155	    favicon: meta.favicon, retrieved: meta.retrieved,
156	    read: false, archived: false, tags: [], note: '',
157	    savedAt: new Date().toISOString() };
158	  bookmarks.unshift(entry);
159	  json(res, 200, { bookmark: entry, duplicate: false });
160	}
161	
162	async function handleField(req, res, field) {
163	  const body = await readBody(req);
164	  let id, value;
165	  try { ({ id, value } = JSON.parse(body)); } catch {}
166	  if (typeof value !== 'boolean') return json(res, 400, { error: 'bad_value' });
167	  const b = bookmarks.find((x) => x.id === id);
168	  if (!b) return json(res, 404, { error: 'not_found' });
169	  b[field] = value;
170	  json(res, 200, { bookmark: b });
171	}
172	
173	function faviconFor(host) {
174	  return `https://www.google.com/s2/favicons?domain=${host}&sz=64`;
175	}
