    note:'# A long formatted note\\n\\n'+Array(11).join('This note has a lot of content to see how a long note reads. ')+'\\n\\n- first point\\n- second point\\n- third point',
    savedAt:new Date().toISOString()};
}
function genMany(){
  var arr=[],sites=['example.com','blog.dev','news.org','docs.io','shop.net'],tg=['reading','ref','ideas','work','fun','web','css'];
  for(var i=1;i<=300;i++){arr.push({id:100000+i,url:'https://'+sites[i%5]+'/article-'+i,key:'k'+i,
    title:'Sample bookmark #'+i+' — a saved link for testing long lists',
    description:'Synthetic entry '+i+' used to preview how a large library looks and scrolls.',
    siteName:sites[i%5],favicon:'https://www.google.com/s2/favicons?domain='+sites[i%5]+'&sz=64',
    retrieved:true,read:(i%3===0),archived:(i%7===0),tags:[tg[i%tg.length],tg[(i+2)%tg.length]],note:'',
    savedAt:new Date(Date.now()-i*3600000).toISOString()});}
  return arr;
}
function applyDemo(){
  var demo=(new URLSearchParams(location.search).get('demo')||'').toLowerCase();
