  else if(demo==='many'){items=genMany();}
  else return;
  bar.hidden=false;
  bar.innerHTML='Preview state: <b>'+esc(demo)+'</b> — for reviewing this edge case only. '+
    '<a href="./">Back to the normal library</a>.';
}

