function render(freshId){
  renderTabs();renderFilter();refreshDatalist();
  var searching=query.trim().length>0;
  // Search stays within the current view (All / Unread / Archived).
  var ast=searching?parseQuery(query):null;
  var hiTerms=[];if(searching)collectHi(ast,false,hiTerms);
  var base=items.filter(function(b){return inView(b,active);});
  var shown=base.filter(matchesTags).filter(function(b){
    return !searching||evalAst(ast,searchHay(b),b.tags);});
  if(searching){
    searchHead.hidden=false;
    searchHead.innerHTML=shown.length+(shown.length===1?' result':' results')+
      ' in <b>'+VIEW_LABEL[active]+'</b> for <span class="qq">'+esc(query.trim())+'</span>';
  }else{searchHead.hidden=true;searchHead.innerHTML='';}
  if(!shown.length){
    var msg;
    if(searching) msg='No '+VIEW_LABEL[active].toLowerCase()+' links match “'+esc(query.trim())+'”.';
    else if(activeTags.length) msg='No '+VIEW_LABEL[active].toLowerCase()+' links tagged '+
      activeTags.map(function(t){return '"'+esc(t)+'"';}).join(' + ')+'.';
    else msg={all:'Your library is empty.',unread:'Nothing unread — you\\'re all caught up.',archived:'Nothing archived.'}[active];
    listEl.innerHTML='<div class="empty"><div class="big">'+msg+'</div>'+
      (active==='all'&&!activeTags.length&&!searching?'<div>Paste a link above to add something.</div>':'')+'</div>';
    return;
  }
  listEl.innerHTML=shown.map(function(b){
    var cls='item'+(b.id===freshId?' fresh':'')+(b.read&&!b.archived?' read':'');
    if(editingEntryId===b.id) return editRow(b,cls);
    var flag=b.retrieved?'':'<span class="flag">details couldn\\'t be fetched</span>';
    var desc=b.description?'<p class="d">'+hi(b.description,hiTerms)+'</p>':'';
    return '<li class="'+cls+'" data-id="'+b.id+'">'+favHtml(b)+
      '<div class="body">'+
        '<h3 class="t"><a href="'+esc(b.url)+'" target="_blank" rel="noopener">'+hi(b.title,hiTerms)+'</a></h3>'+desc+
        noteHtml(b)+
        '<div class="meta">'+badge(b)+'<span class="site">'+esc(b.siteName)+'</span>'+
          '<span class="dot">·</span><span>'+whenLabel(b.savedAt)+'</span>'+
          (flag?'<span class="dot">·</span>'+flag:'')+'</div>'+
        tagsHtml(b)+controls(b)+
      '</div></li>';
  }).join('');
  if(editingEntryId!=null){
    var ef=listEl.querySelector('li.item[data-id="'+editingEntryId+'"] [data-ef="title"]');
    if(ef)ef.focus();
  }
  if(editingTagId!=null){
    var inp=listEl.querySelector('[data-taginput="'+editingTagId+'"]');
    if(inp)inp.focus();
  }
}

function goToEntry(id){var el=listEl.querySelector('li.item[data-id="'+id+'"]');
  if(!el)return;el.scrollIntoView({behavior:'smooth',block:'center'});
  el.classList.remove('flash');void el.offsetWidth;el.classList.add('flash');}

