7	//   * clearer invalid-address message; persistent Search tips; demo states
8	//     (?demo=empty|long|many) for reviewing edge cases
9	// Search: within the current view (All / Unread / Archived) across titles,
10	//   descriptions, tags, notes, address; query language #tag / "phrase" /
11	//   AND / OR / NOT / ( ); matches highlighted. Carries all approved behaviour.
12	// Exploration prototype only — NOT production code; must not seed Phase 2.
13	
14	const http = require('http');
15	
16	const PORT = 4001;
17	const HOST = '0.0.0.0';
18	
19	/** In-memory store (prototype only). Each entry: {read, archived, tags:[]}. */
20	const bookmarks = [];
21	let nextId = 1;
22	
23	function seed() {
24	  const now = Date.now();
25	  const samples = [
26	    { url: 'https://developer.mozilla.org/en-US/docs/Web/CSS/Grid',
27	      title: 'CSS Grid Layout — MDN',
28	      description: 'A two-dimensional layout system for the web, with rows and columns.',
29	      siteName: 'developer.mozilla.org', read: false, archived: false, ageMin: 8,
30	      tags: ['css', 'reference', 'web'] },
31	    { url: 'https://www.nngroup.com/articles/progressive-disclosure/',
32	      title: 'Progressive Disclosure — Nielsen Norman Group',
33	      description: 'Defer advanced or rarely used features to a secondary screen to keep interfaces calm.',
34	      siteName: 'nngroup.com', read: false, archived: false, ageMin: 40,
35	      tags: ['ux', 'reading', 'web'],
36	      note: 'Re-read before redesigning the settings screen.' },
37	    { url: 'https://en.wikipedia.org/wiki/Zettelkasten',
38	      title: 'Zettelkasten — Wikipedia',
39	      description: 'A method of personal knowledge management and note-taking.',
40	      siteName: 'en.wikipedia.org', read: true, archived: false, ageMin: 130,
41	      tags: ['notes', 'method', 'reading'] },
42	    { url: 'https://www.gutenberg.org/ebooks/1342',
43	      title: 'Pride and Prejudice, by Jane Austen — Project Gutenberg',
44	      description: 'The complete text, free to read.',
45	      siteName: 'gutenberg.org', read: true, archived: true, ageMin: 1500,
46	      tags: ['book'] },
47	    { url: 'https://web.archive.org/',
48	      title: 'Internet Archive: Wayback Machine',
