50	      siteName: 'web.archive.org', read: false, archived: true, ageMin: 6000,
51	      tags: ['tools', 'reference'] },
52	  ];
53	  for (const s of samples) {
54	    const host = new URL(s.url).hostname.replace(/^www\./, '');
55	    bookmarks.push({
56	      id: nextId++, url: s.url, key: canonicalKey(s.url),
57	      title: s.title, description: s.description, siteName: s.siteName,
58	      favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`,
59	      retrieved: true, read: s.read, archived: s.archived, tags: s.tags.slice(),
60	      note: s.note || '',
61	      savedAt: new Date(now - s.ageMin * 60000).toISOString(),
62	    });
63	  }
64	  bookmarks.sort((a, b) => new Date(b.savedAt) - new Date(a.savedAt));
65	}
66	
67	// ---- metadata retrieval -----------------------------------------------------
68	
69	function decodeEntities(s) {
70	  if (!s) return s;
71	  return s
72	    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
73	    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&#x27;/g, "'")
74	    .replace(/&nbsp;/g, ' ')
75	    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)))
76	    .trim();
77	}
78	function metaContent(html, patterns) {
79	  for (const re of patterns) {
80	    const m = re.exec(html);
81	    if (m && m[1] && m[1].trim()) return decodeEntities(m[1]);
82	  }
83	  return '';
84	}
85	function normalizeUrl(raw) {
86	  let u = (raw || '').trim();
87	  if (!u) return '';
88	  if (!/^https?:\/\//i.test(u)) u = 'https://' + u;
89	  try { return new URL(u).toString(); } catch { return ''; }
90	}
91	function canonicalKey(url) {
92	  try {
93	    const p = new URL(url);
94	    const host = p.hostname.replace(/^www\./, '').toLowerCase();
95	    let path = p.pathname.replace(/\/+$/, '');
96	    if (path === '') path = '/';
97	    return host + path + p.search;
98	  } catch { return url; }
99	}
100	async function fetchMetadata(url) {
101	  const parsed = new URL(url);
102	  const host = parsed.hostname.replace(/^www\./, '');
103	  const result = { title: '', description: '', siteName: host,
104	    favicon: `https://www.google.com/s2/favicons?domain=${host}&sz=64`, retrieved: false };
105	  try {
106	    const controller = new AbortController();
107	    const timer = setTimeout(() => controller.abort(), 8000);
108	    const res = await fetch(url, {
109	      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BookmarkPrototype/1.0)' },
110	      signal: controller.signal, redirect: 'follow' });
111	    clearTimeout(timer);
112	    const html = (await res.text()).slice(0, 400000);
113	    result.title = metaContent(html, [
114	      /<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["']/i,
115	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:title["']/i,
116	      /<meta[^>]+name=["']twitter:title["'][^>]+content=["']([^"']+)["']/i,
117	      /<title[^>]*>([\s\S]*?)<\/title>/i ]);
118	    result.description = metaContent(html, [
119	      /<meta[^>]+property=["']og:description["'][^>]+content=["']([^"']*)["']/i,
120	      /<meta[^>]+content=["']([^"']*)["'][^>]+property=["']og:description["']/i,
121	      /<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i,
122	      /<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i ]);
123	    const site = metaContent(html, [
124	      /<meta[^>]+property=["']og:site_name["'][^>]+content=["']([^"']+)["']/i,
125	      /<meta[^>]+content=["']([^"']+)["'][^>]+property=["']og:site_name["']/i ]);
126	    if (site) result.siteName = site;
127	    result.retrieved = true;
128	  } catch { result.retrieved = false; }
129	  if (!result.title) result.title = host + parsed.pathname.replace(/\/$/, '');
130	  return result;
131	}
132	
133	// ---- api --------------------------------------------------------------------
134	
135	function readBody(req) {
136	  return new Promise((resolve) => {
137	    let data = '';
138	    req.on('data', (c) => (data += c));
139	    req.on('end', () => resolve(data));
140	  });
141	}
142	function json(res, code, obj) {
143	  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8' });
144	  res.end(JSON.stringify(obj));
145	}
146	function normTag(t) { return (t || '').trim().replace(/\s+/g, ' ').slice(0, 40); }
147	
148	async function handleSave(req, res) {
149	  const body = await readBody(req);
150	  let url = '';
151	  try { url = JSON.parse(body).url; } catch {}
152	  const normalized = normalizeUrl(url);
153	  if (!normalized) return json(res, 400, { error: 'invalid_url' });
154	  const key = canonicalKey(normalized);
155	  const existing = bookmarks.find((b) => b.key === key);
156	  if (existing) return json(res, 200, { bookmark: existing, duplicate: true });
157	  const meta = await fetchMetadata(normalized);
158	  const entry = {
159	    id: nextId++, url: normalized, key,
160	    title: meta.title, description: meta.description, siteName: meta.siteName,
161	    favicon: meta.favicon, retrieved: meta.retrieved,
162	    read: false, archived: false, tags: [], note: '',
163	    savedAt: new Date().toISOString() };
164	  bookmarks.unshift(entry);
165	  json(res, 200, { bookmark: entry, duplicate: false });
166	}
