async function handleDelete(req, res) {
  const body = await readBody(req);
  let id;
  try { ({ id } = JSON.parse(body)); } catch {}
  const idx = bookmarks.findIndex((x) => x.id === id);
  if (idx < 0) return json(res, 404, { error: 'not_found' });
  bookmarks.splice(idx, 1);
  json(res, 200, { ok: true });
}

// Apply one action to many links at once.
async function handleBulk(req, res) {
  const body = await readBody(req);
  let ids, action, value;
  try { ({ ids, action, value } = JSON.parse(body)); } catch {}
  if (!Array.isArray(ids)) return json(res, 400, { error: 'bad_ids' });
  const idset = new Set(ids);
  if (action === 'delete') {
    for (let i = bookmarks.length - 1; i >= 0; i--) if (idset.has(bookmarks[i].id)) bookmarks.splice(i, 1);
    return json(res, 200, { ok: true });
  }
  const targets = bookmarks.filter((b) => idset.has(b.id));
  for (const b of targets) {
    if (action === 'read') b.read = true;
    else if (action === 'unread') b.read = false;
    else if (action === 'archive') b.archived = true;
    else if (action === 'restore') b.archived = false;
    else if (action === 'addtag') {
      const t = normTag(value);
      if (t && !b.tags.some((x) => x.toLowerCase() === t.toLowerCase())) b.tags.push(t);
    } else if (action === 'removetag') {
      const t = normTag(value);
      if (t) b.tags = b.tags.filter((x) => x.toLowerCase() !== t.toLowerCase());
    }
  }
  json(res, 200, { ok: true, count: targets.length });
}

