function renderBulk(){
  var n=currentMatchIds.length;
  var allSel=n>0&&currentMatchIds.every(function(id){return selectedIds[id];});
  selAllEl.checked=allSel;
  selAllEl.indeterminate=(!allSel&&currentMatchIds.some(function(id){return selectedIds[id];}));
  selAllLabel.textContent='Select all'+(n?' ('+n+')':'');
  var c=selCount();
  if(!c){bulkbarEl.hidden=true;bulkbarEl.innerHTML='';bulkMode='none';return;}
  bulkbarEl.hidden=false;
  if(bulkMode==='addtag'||bulkMode==='removetag'){
    bulkbarEl.innerHTML='<span class="bcount">'+c+' selected</span>'+
      '<input id="bulktag" list="alltags" placeholder="'+(bulkMode==='addtag'?'tag to add…':'tag to remove…')+'">'+
      '<button data-bulkapply>'+(bulkMode==='addtag'?'Add tag':'Remove tag')+'</button>'+
      '<button data-bulkcancel>Cancel</button>';
    var inp=bulkbarEl.querySelector('#bulktag');if(inp)inp.focus();return;
  }
  if(bulkMode==='confirmdelete'){
    bulkbarEl.innerHTML='<span class="bcount warn">Delete '+c+' permanently?</span>'+
      '<span class="warn">This can’t be undone.</span>'+
      '<button class="danger" data-bulk="delete">Delete '+c+' permanently</button>'+
      '<button data-bulkcancel>Cancel</button>';return;
  }
  bulkbarEl.innerHTML='<span class="bcount">'+c+' selected</span>'+
    '<button data-bulk="read">Mark read</button>'+
    '<button data-bulk="unread">Mark unread</button>'+
    (active==='archived'?'<button data-bulk="restore">Restore</button>':'<button data-bulk="archive">Archive</button>')+
    '<button data-bulkmode="addtag">Add tag…</button>'+
    '<button data-bulkmode="removetag">Remove tag…</button>'+
    '<button class="danger" data-bulkmode="confirmdelete">Delete…</button>'+
    '<span class="spacer"></span><button data-bulkclear>Clear</button>';
}
function bulkMsg(a,n,v){
  if(a==='read')return 'Marked '+n+' as read.';
  if(a==='unread')return 'Marked '+n+' as unread.';
  if(a==='archive')return 'Archived '+n+'.';
  if(a==='restore')return 'Restored '+n+'.';
  if(a==='addtag')return 'Tagged '+n+' with “'+esc(v)+'”.';
  if(a==='removetag')return 'Removed “'+esc(v)+'” from '+n+'.';
  if(a==='delete')return 'Deleted '+n+' permanently.';
  return 'Done.';
}
function bulkApply(action,value){
  var ids=Object.keys(selectedIds).map(Number);
  if(!ids.length)return;
  var idset={};ids.forEach(function(i){idset[i]=true;});
  if(action==='delete'){
    items=items.filter(function(b){return !idset[b.id];});
  }else{
    items.forEach(function(b){if(!idset[b.id])return;
      if(action==='read')b.read=true;else if(action==='unread')b.read=false;
      else if(action==='archive')b.archived=true;else if(action==='restore')b.archived=false;
      else if(action==='addtag'){var t=(value||'').trim();if(t&&!b.tags.some(function(x){return x.toLowerCase()===t.toLowerCase();}))b.tags.push(t);}
      else if(action==='removetag'){var t2=(value||'').trim();if(t2)b.tags=b.tags.filter(function(x){return x.toLowerCase()!==t2.toLowerCase();});}
    });
  }
  fetch('/api/bulk',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({ids:ids,action:action,value:value})}).catch(function(){});
  selectedIds={};bulkMode='none';render();showNotice(bulkMsg(action,ids.length,value));
}
function deleteEntry(id){
  items=items.filter(function(b){return b.id!==id;});delete selectedIds[id];
  fetch('/api/delete',{method:'POST',headers:{'Content-Type':'application/json'},
    body:JSON.stringify({id:id})}).catch(function(){});
  editingEntryId=null;confirmingDeleteId=null;render();showNotice('Deleted permanently.');
}
function delRow(b){
  if(confirmingDeleteId===b.id){
    return '<div class="delrow"><span class="delwarn">Delete this link permanently? This can’t be undone.</span>'+
      '<button class="btn danger" data-delyes="'+b.id+'">Delete permanently</button>'+
      '<button class="btn" data-delno>Keep</button></div>';
  }
  return '<div class="delrow"><button class="btn danger-ghost" data-delask="'+b.id+'">🗑 Delete permanently…</button></div>';
}

