.bulkbar{position:sticky;top:84px;z-index:6;background:#2f3a2c;color:#eef0e9;border-radius:12px;box-shadow:var(--shadow);
  padding:10px 14px;margin-bottom:16px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.bulkbar[hidden]{display:none}
.bulkbar .bcount{font-weight:600;margin-right:6px}
.bulkbar button{font:inherit;font-size:13px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.08);
  color:#eef0e9;padding:6px 11px;border-radius:8px;cursor:pointer}
.bulkbar button:hover{background:rgba(255,255,255,.16)}
.bulkbar button.danger{border-color:#e2a3a3;color:#ffd9d9}
.bulkbar button.danger:hover{background:rgba(226,120,120,.28)}
.bulkbar input{font:inherit;font-size:13px;border:1px solid rgba(255,255,255,.3);border-radius:8px;padding:6px 9px;background:#fff;color:#23201b;min-width:150px}
.bulkbar .spacer{flex:1}
.bulkbar .warn{color:#ffdede}

.review{background:var(--card);border:1px solid #cdd6c4;border-radius:14px;box-shadow:0 0 0 2px var(--accent-soft),var(--shadow);
  padding:16px 18px;margin:0 0 22px}
.review[hidden]{display:none}
.review .rh{font-size:12px;font-weight:700;color:var(--accent);text-transform:uppercase;letter-spacing:.04em;margin-bottom:10px}
.review .rimg{width:100%;max-height:180px;object-fit:cover;border-radius:10px;border:1px solid var(--line);margin-bottom:6px}
.review .rurl{font-size:12.5px;color:var(--muted);word-break:break-all;margin-bottom:10px}
.review label{font-size:12px;font-weight:600;color:#6f6a60;display:block;margin:8px 0 3px}
.review input,.review textarea{width:100%;font:inherit;font-size:14px;color:var(--ink);border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:#fff;outline:none;resize:vertical}
.review input:focus,.review textarea:focus{border-color:var(--accent)}
.review .row{display:flex;gap:8px;margin-top:12px}

ul.list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:14px}
li.item{background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);
  padding:16px 18px;display:flex;gap:14px;align-items:flex-start}
li.item.read{opacity:.82}
li.item.selected{box-shadow:0 0 0 2px var(--accent),var(--shadow)}
li.item.flash{animation:flash 1.6s ease}
@keyframes flash{0%{box-shadow:0 0 0 3px #d9c48f,var(--shadow);background:#fdf7e6}100%{box-shadow:var(--shadow);background:var(--card)}}
.selbox{margin:2px 0 0;width:18px;height:18px;flex:none;cursor:pointer;accent-color:var(--accent)}
.fav{width:34px;height:34px;border-radius:8px;flex:none;background:var(--accent-soft);display:flex;align-items:center;justify-content:center;overflow:hidden}
.fav img{width:20px;height:20px}
.body{min-width:0;flex:1}
.body .t{font-size:16.5px;font-weight:600;letter-spacing:-.005em;margin:0 0 3px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.body .t a{color:var(--ink);text-decoration:none}.body .t a:hover{text-decoration:underline}
.body .d{color:#5f5b53;font-size:14px;margin:0 0 8px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.body .meta{color:var(--muted);font-size:12.5px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
