.saver{position:sticky;top:16px;z-index:5;background:var(--card);border:1px solid var(--line);
  border-radius:14px;box-shadow:var(--shadow);padding:14px;margin-bottom:16px;display:flex;gap:10px;align-items:center}
.saver input{flex:1;border:none;outline:none;background:transparent;font-size:16px;color:var(--ink);padding:8px 6px}
.saver input::placeholder{color:#b4afa5}
.saver button.save{border:none;background:var(--accent);color:#fff;font-size:15px;font-weight:500;
  padding:10px 18px;border-radius:10px;cursor:pointer;transition:opacity .15s,transform .05s}
.saver button.save:hover{opacity:.92}.saver button.save:active{transform:translateY(1px)}
.saver button.save:disabled{opacity:.55;cursor:default}

.searchbar{display:flex;align-items:center;gap:9px;background:var(--card);border:1px solid var(--line);
  border-radius:12px;padding:9px 13px;margin-bottom:16px}
.searchbar .mag{opacity:.45;font-size:15px}
.searchbar input{flex:1;border:none;outline:none;background:transparent;font-size:15px;color:var(--ink)}
.searchbar input::placeholder{color:#b4afa5}
.sclear{border:none;background:none;color:var(--muted);cursor:pointer;font-size:15px;padding:2px 6px;border-radius:6px}
.sclear:hover{background:#f2f0ea;color:#5f5b53}
.tips-link{border:none;background:none;color:var(--accent);cursor:pointer;font:inherit;font-size:12.5px;white-space:nowrap;padding:2px 4px;border-radius:6px}
.tips-link:hover{text-decoration:underline}
.tips-panel{background:var(--card);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);
  padding:12px 14px;margin:-6px 2px 16px;font-size:13px;color:#5f5b53}
.tips-panel[hidden]{display:none}
.tips-panel h4{margin:0 0 6px;font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:#8a857c}
.tips-panel ul{margin:0;padding-left:18px}
.tips-panel li{margin:3px 0}
.tips-panel code{background:#efece5;border-radius:4px;padding:0 5px;color:#4a4640}

.searchhead{margin:0 2px 14px;font-size:13.5px;color:#6f6a60;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.searchhead b{color:var(--ink)}
.searchhead .qq{font-weight:600;color:var(--accent)}
mark{background:#fbefc4;color:inherit;border-radius:3px;padding:0 1px}

.notice{margin:0 4px 16px;font-size:14px;color:#6f6a60;background:#fbf6e9;border:1px solid #ecdfbf;
  border-radius:10px;padding:9px 13px;display:flex;gap:8px;align-items:center}
.notice b{color:#4a4640;font-weight:600}
.notice.error{background:#f8e9e9;border-color:#ecc9c9;color:#8a4a4a}

.tabs{display:flex;gap:6px;margin:0 0 14px;border-bottom:1px solid var(--line)}
.tab{border:none;background:none;font:inherit;font-size:14.5px;color:var(--muted);cursor:pointer;
  padding:9px 12px;border-bottom:2px solid transparent;margin-bottom:-1px;display:flex;gap:7px;align-items:center}
.tab:hover{color:#5f5b53}
.tab.active{color:var(--ink);border-bottom-color:var(--accent);font-weight:600}
.tab .n{font-size:12px;color:var(--muted);background:var(--accent-soft);border-radius:999px;padding:1px 7px}
.tab.active .n{color:var(--accent)}

.filterbar{margin:0 2px 12px;font-size:13.5px;color:#6f6a60;display:none;gap:8px;align-items:center;flex-wrap:wrap}
.filterbar.on{display:flex}
.filterbar .ftag{font-weight:600;color:var(--accent);background:var(--accent-soft);border-radius:999px;padding:2px 10px;cursor:pointer}
.filterbar .ftag:hover{background:#e2e7d9}
.filterbar button{font:inherit;font-size:12.5px;border:1px solid var(--line);background:#fbfaf8;color:#6f6a60;padding:3px 10px;border-radius:999px;cursor:pointer}
.filterbar button:hover{background:#f2f0ea}

.listbar{display:flex;justify-content:space-between;align-items:center;gap:8px;margin:0 2px 12px;font-size:13px;color:var(--muted)}
.listbar .sortwrap{display:flex;gap:8px;align-items:center}
.listbar select{font:inherit;font-size:13px;color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:5px 8px;background:#fff;cursor:pointer}
.selall{display:flex;gap:7px;align-items:center;color:#6f6a60;cursor:pointer}
.selall input{width:16px;height:16px;accent-color:var(--accent);cursor:pointer}

.bulkbar{position:sticky;top:84px;z-index:6;background:#2f3a2c;color:#eef0e9;border-radius:12px;box-shadow:var(--shadow);
  padding:10px 14px;margin-bottom:16px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.bulkbar[hidden]{display:none}
.bulkbar .bcount{font-weight:600;margin-right:6px}
.bulkbar button{font:inherit;font-size:13px;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.08);
  color:#eef0e9;padding:6px 11px;border-radius:8px;cursor:pointer}
.bulkbar button:hover{background:rgba(255,255,255,.16)}
.bulkbar button.danger{border-color:#e2a3a3;color:#ffd9d9}
.bulkbar button.danger:hover{background:rgba(226,120,120,.28)}
.bulkbar input{font:inherit;font-size:13px;border:1px solid rgba(255,255,255,.3);border-radius:8px;padding:6px 9px;background:#fff;color:#23201b;min-width:150px}
.bulkbar .spacer{flex:1}
.bulkbar .warn{color:#ffdede}

.review{background:var(--card);border:1px solid #cdd6c4;border-radius:14px;box-shadow:0 0 0 2px var(--accent-soft),var(--shadow);
  padding:16px 18px;margin:0 0 22px}
.review[hidden]{display:none}
.review .rh{font-size:12px;font-weight:700;color:var(--accent);text-transform:uppercase;letter-spacing:.04em;margin-bottom:10px}
.review .rimg{width:100%;max-height:180px;object-fit:cover;border-radius:10px;border:1px solid var(--line);margin-bottom:6px}
.review .rurl{font-size:12.5px;color:var(--muted);word-break:break-all;margin-bottom:10px}
.review label{font-size:12px;font-weight:600;color:#6f6a60;display:block;margin:8px 0 3px}
.review input,.review textarea{width:100%;font:inherit;font-size:14px;color:var(--ink);border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:#fff;outline:none;resize:vertical}
.review input:focus,.review textarea:focus{border-color:var(--accent)}
.review .row{display:flex;gap:8px;margin-top:12px}

ul.list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:14px}
li.item{background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow);
  padding:16px 18px;display:flex;gap:14px;align-items:flex-start}
li.item.read{opacity:.82}
li.item.selected{box-shadow:0 0 0 2px var(--accent),var(--shadow)}
li.item.flash{animation:flash 1.6s ease}
@keyframes flash{0%{box-shadow:0 0 0 3px #d9c48f,var(--shadow);background:#fdf7e6}100%{box-shadow:var(--shadow);background:var(--card)}}
.selbox{margin:2px 0 0;width:18px;height:18px;flex:none;cursor:pointer;accent-color:var(--accent)}
.fav{width:34px;height:34px;border-radius:8px;flex:none;background:var(--accent-soft);display:flex;align-items:center;justify-content:center;overflow:hidden}
.fav img{width:20px;height:20px}
.body{min-width:0;flex:1}
.body .t{font-size:16.5px;font-weight:600;letter-spacing:-.005em;margin:0 0 3px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.body .t a{color:var(--ink);text-decoration:none}.body .t a:hover{text-decoration:underline}
.body .d{color:#5f5b53;font-size:14px;margin:0 0 8px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.body .meta{color:var(--muted);font-size:12.5px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.body .meta .site{font-weight:500;color:#6f6a60}
.body .meta .dot{opacity:.5}
.flag{font-size:11.5px;color:#9a7b3f;background:#f6efe0;padding:2px 8px;border-radius:999px}
.sb{font-size:11.5px;font-weight:600;padding:2px 9px;border-radius:999px;white-space:nowrap}
.sb.unread{color:#3f5a74;background:#e6eef6}
.sb.read{color:#3f6b4f;background:#e6f1e9}
.sb.arch{color:#7a736a;background:#eeece7}

.note{margin:9px 0 0;font-size:13.5px;color:#5a5347;background:#fbf7ee;border-left:3px solid #d9c48f;border-radius:0 8px 8px 0;padding:8px 12px}
.note .nlab{display:block;font-size:11px;font-weight:600;color:#9a8a5f;text-transform:uppercase;letter-spacing:.04em;margin-bottom:4px}
.note .md>*:first-child{margin-top:0}.note .md>*:last-child{margin-bottom:0}
.note .md p{margin:6px 0}
.note .md h4,.note .md h5,.note .md h6{margin:8px 0 4px;color:#4a4238;line-height:1.3}
.note .md h4{font-size:15px}.note .md h5{font-size:13.5px}.note .md h6{font-size:12.5px}
.note .md ul,.note .md ol{margin:5px 0;padding-left:20px}.note .md li{margin:2px 0}
.note .md a{color:var(--accent);text-decoration:underline}.note .md strong{color:#43403a}
.note.clamp .md{max-height:84px;overflow:hidden;position:relative}
.note.clamp .md::after{content:'';position:absolute;left:0;right:0;bottom:0;height:34px;background:linear-gradient(to bottom,rgba(251,247,238,0),#fbf7ee)}
.notemore{border:none;background:none;color:var(--accent);cursor:pointer;font:inherit;font-size:12.5px;padding:4px 0 0;font-weight:500}
.notemore:hover{text-decoration:underline}

.tags{margin-top:10px;display:flex;gap:6px;align-items:center;flex-wrap:wrap}
.chip{font-size:12px;color:#55606a;background:#eef1f4;border:1px solid #e2e7ec;border-radius:999px;padding:2px 4px 2px 10px;display:inline-flex;gap:5px;align-items:center}
.chip.on{background:var(--accent-soft);border-color:#cdd6c4}.chip.on .lab{color:var(--accent)}
.chip .lab{cursor:pointer}.chip .lab:hover{color:#2f3a44;text-decoration:underline}
.chip .x{cursor:pointer;color:#a7adb4;width:16px;height:16px;border-radius:999px;display:inline-flex;align-items:center;justify-content:center;font-size:12px}
.chip .x:hover{background:#dfe4e9;color:#6b7178}
.addtag{font-size:12px;color:var(--muted);background:none;border:1px dashed #d6d2c9;border-radius:999px;padding:3px 10px;cursor:pointer}
.addtag:hover{color:#5f5b53;border-color:#c2bdb2;background:#faf9f6}
.taginput{font:inherit;font-size:12px;border:1px solid var(--accent);border-radius:999px;padding:3px 10px;outline:none;width:130px}

.ctrls{margin-top:11px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.btn{font:inherit;font-size:12.5px;border:1px solid var(--line);background:#fbfaf8;color:#5f5b53;padding:6px 12px;border-radius:8px;cursor:pointer;transition:background .12s,border-color .12s}
.btn:hover{background:#f2f0ea;border-color:#dcd8cf}
.btn.primary{border-color:#cdd6c4;background:var(--accent-soft);color:var(--accent)}
.btn.danger-ghost{border-color:#e6c4c4;color:#9a3f3f;background:#fbf1f1}.btn.danger-ghost:hover{background:#f6e6e6}
.btn.danger{border-color:#c98a8a;color:#fff;background:#a45151}.btn.danger:hover{background:#8f4444}

.editform{margin-top:4px;display:flex;flex-direction:column;gap:9px}
.editform label{font-size:12px;font-weight:600;color:#6f6a60;display:block;margin-bottom:3px}
.editform input,.editform textarea{width:100%;font:inherit;font-size:14px;color:var(--ink);border:1px solid var(--line);border-radius:9px;padding:8px 10px;background:#fff;outline:none;resize:vertical}
.editform input:focus,.editform textarea:focus{border-color:var(--accent)}
.editform .row{display:flex;gap:8px;margin-top:2px}
.editform .eimg{width:100%;max-height:160px;object-fit:cover;border-radius:10px;border:1px solid var(--line);margin-bottom:4px}
.fmthint{font-size:11.5px;color:#9a958b;margin-top:3px}
.fmthint code{background:#efece5;border-radius:4px;padding:0 4px}
.ef-error{font-size:12.5px;color:#9a3f3f;background:#f8e9e9;border:1px solid #ecc9c9;border-radius:8px;padding:7px 10px;margin-top:4px}
.delrow{margin-top:12px;padding-top:10px;border-top:1px dashed var(--line);display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.delwarn{font-size:12.5px;color:#9a3f3f}

.loadmore{display:flex;justify-content:center;margin-top:18px}
.loadmore button{font:inherit;font-size:14px;color:var(--accent);background:var(--accent-soft);border:1px solid #cdd6c4;border-radius:10px;padding:10px 20px;cursor:pointer}
.loadmore button:hover{background:#e6ebdd}

.empty{text-align:center;color:var(--muted);padding:56px 20px}
.empty .big{font-size:17px;color:#6f6a60;margin-bottom:6px}

@media (max-width:560px){
  .wrap{padding:24px 14px 80px}
  .saver{flex-direction:column;align-items:stretch}.saver button.save{width:100%}
}

